update stock
set quantity = quantity - #{quantity},
    outbound_quantity = outbound_quantity + #{quantity},
    updated_at = now()
where warehouse_id = #{warehouseId}
  and material_id = #{materialId}
  and material_batch_id = #{materialBatchId}
