for update

SELECT iod.material_type as material_type, iod.agricultural_input_type as agricultural_input_type, SUM(s.quantity) as total_quantity, CASE WHEN iod.material_type = 'seed' THEN 'kg' WHEN iod.material_type = 'fertilizer' THEN 'kg' WHEN iod.material_type = 'pesticide' THEN 'L' ELSE 'unit' END as unit FROM stock s LEFT JOIN inv_warehouse w ON s.warehouse_id = w.warehouse_id AND w.del_flag = '0' LEFT JOIN inbound_order_detail iod ON s.material_batch_id = iod.batch_no
AND s.warehouse_id = #{params.warehouseId}
AND iod.material_type = #{params.materialType}
AND iod.agricultural_input_type = #{params.agriculturalInputType}
AND w.organ_code = #{params.organCode}
AND s.quantity >= #{params.minQuantity}
GROUP BY iod.material_type, iod.agricultural_input_type

SELECT s.* 
FROM stock s
WHERE s.warehouse_id = #{warehouseId}
  AND s.material_type = #{inputType}
  AND s.agricultural_input_type = #{agriculturalInputType}
  AND s.quantity > 0
  AND s.status = '0'
  AND (s.expiry_date is null or s.expiry_date > curdate())
ORDER BY s.created_at
